import React, { useState, useEffect } from 'react';

const AnalyticsDashboard = () => {
    const [analyticsData, setAnalyticsData] = useState({
        totalUsers: 0,
        totalMatches: 0,
        totalMessages: 0,
        activeUsers: 0,
        avgDistance: '12 km' // Placeholder for distance
    });
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchAnalytics = async () => {
            try {
                // Assuming API has an endpoint /admin/stats configured in api.js or direct fetch
                const response = await fetch(`${process.env.REACT_APP_API_URL || `http://${window.location.hostname}:5000`}/admin/stats`);
                if (response.ok) {
                    const data = await response.json();
                    setAnalyticsData({
                        totalUsers: data.total_users || 0,
                        totalMatches: data.total_matches || 0,
                        totalMessages: data.total_messages || 0,
                        activeUsers: data.active_users || 0,
                        avgDistance: '14.2 km' // Placeholder until backend calculates geospatial distances
                    });
                }
            } catch (err) {
                console.error("Failed to fetch analytics:", err);
            } finally {
                setLoading(false);
            }
        };

        fetchAnalytics();
    }, []);

    if (loading) return (
        <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', height: '100%', minHeight: '500px' }}>
            <div style={{ padding: '30px', fontSize: '1.2rem', color: '#64748b', fontWeight: '600' }}>Loading analytics...</div>
        </div>
    );

    return (
        <div style={{ padding: '30px', maxWidth: '1400px', margin: '0 auto', width: '100%' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '40px', flexWrap: 'wrap', gap: '15px' }}>
                <h1 style={{ fontSize: '2.5rem', color: '#0f172a', margin: 0, fontWeight: '800', letterSpacing: '-0.5px' }}>
                    📈 Analytics Dashboard
                </h1>
                <div style={{ padding: '8px 16px', backgroundColor: '#f1f5f9', borderRadius: '20px', color: '#475569', fontWeight: '700', fontSize: '0.9rem' }}>
                    Real-time Data Active
                </div>
            </div>

            {/* KPI Stat Cards */}
            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(220px, 1fr))', gap: '24px', marginBottom: '50px' }}>
                <KpiCard title="Total Users" value={analyticsData.totalUsers} gradient="linear-gradient(135deg, #3b82f6 0%, #2563eb 100%)" icon="👥" />
                <KpiCard title="Total Matches" value={analyticsData.totalMatches} gradient="linear-gradient(135deg, #e11d48 0%, #be123c 100%)" icon="❤️" />
                <KpiCard title="Total Messages" value={analyticsData.totalMessages} gradient="linear-gradient(135deg, #10b981 0%, #059669 100%)" icon="💬" />
                <KpiCard title="Active Users" value={analyticsData.activeUsers} gradient="linear-gradient(135deg, #f59e0b 0%, #d97706 100%)" icon="🔥" />
                <KpiCard title="Avg. Distance" value={analyticsData.avgDistance} gradient="linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%)" icon="📍" />
            </div>

            {/* Landscape Charts (Full Width) */}
            <div style={{ display: 'grid', gridTemplateColumns: '1fr', gap: '30px' }}>
                {/* Chart 1 */}
                <div style={chartContainerStyle}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginBottom: '30px' }}>
                        <h3 style={{ margin: 0, color: '#f8fafc', fontSize: '1.4rem', fontWeight: '700' }}>📊 User Growth Trends</h3>
                        <span style={{ fontSize: '0.85rem', color: '#cbd5e1', backgroundColor: 'rgba(255,255,255,0.1)', padding: '4px 12px', borderRadius: '12px' }}>Last 30 Days</span>
                    </div>
                    <div style={{ width: '100%', height: '220px', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-between', padding: '0 20px', gap: '2%' }}>
                        {[40, 50, 70, 60, 90, 85, 100].map((height, i) => (
                            <div key={i} style={barStyle(height, '#60a5fa')} onMouseOver={(e) => {e.currentTarget.style.opacity = '1'; e.currentTarget.style.transform = 'translateY(-5px)';}} onMouseOut={(e) => {e.currentTarget.style.opacity = '0.7'; e.currentTarget.style.transform = 'translateY(0)';}}>
                            </div>
                        ))}
                    </div>
                </div>

                {/* Chart 2 */}
                <div style={{ ...chartContainerStyle, background: 'linear-gradient(135deg, #1e1b4b 0%, #312e81 100%)', border: '1px solid rgba(139, 92, 246, 0.2)' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', width: '100%', marginBottom: '30px' }}>
                        <h3 style={{ margin: 0, color: '#f8fafc', fontSize: '1.4rem', fontWeight: '700' }}>❤️ Match Engagement</h3>
                        <span style={{ fontSize: '0.85rem', color: '#cbd5e1', backgroundColor: 'rgba(255,255,255,0.1)', padding: '4px 12px', borderRadius: '12px' }}>Weekly Overview</span>
                    </div>
                    <div style={{ width: '100%', height: '220px', display: 'flex', alignItems: 'flex-end', justifyContent: 'space-around', padding: '0 20px', gap: '4%' }}>
                         {[30, 60, 80, 50, 95].map((height, i) => (
                             <div key={i} style={{ ...barStyle(height, '#f43f5e'), borderRadius: '12px 12px 0 0', width: '12%' }} onMouseOver={(e) => {e.currentTarget.style.opacity = '1'; e.currentTarget.style.transform = 'translateY(-5px)';}} onMouseOut={(e) => {e.currentTarget.style.opacity = '0.7'; e.currentTarget.style.transform = 'translateY(0)';}}></div>
                         ))}
                    </div>
                </div>
            </div>
        </div>
    );
};

// Reusable Components & Styles

const KpiCard = ({ title, value, gradient, icon }) => (
    <div 
        style={{ 
            background: gradient, 
            padding: '24px', 
            borderRadius: '20px', 
            boxShadow: '0 10px 15px -3px rgba(0, 0, 0, 0.1), 0 4px 6px -2px rgba(0, 0, 0, 0.05)', 
            display: 'flex', 
            flexDirection: 'column',
            justifyContent: 'space-between',
            color: 'white',
            position: 'relative',
            overflow: 'hidden',
            cursor: 'default',
            transition: 'transform 0.3s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.3s'
        }}
        onMouseOver={(e) => { e.currentTarget.style.transform = 'translateY(-8px)'; e.currentTarget.style.boxShadow = '0 20px 25px -5px rgba(0, 0, 0, 0.2)'; }}
        onMouseOut={(e) => { e.currentTarget.style.transform = 'translateY(0)'; e.currentTarget.style.boxShadow = '0 10px 15px -3px rgba(0, 0, 0, 0.1)'; }}
    >
        <div style={{ position: 'absolute', right: '-10px', top: '-10px', fontSize: '6rem', opacity: '0.15', transform: 'rotate(15deg)', pointerEvents: 'none' }}>
            {icon}
        </div>
        <h3 style={{ margin: '0 0 10px 0', fontSize: '1.05rem', fontWeight: '700', opacity: 0.9, textTransform: 'uppercase', letterSpacing: '0.5px' }}>{title}</h3>
        <p style={{ margin: 0, fontSize: '2.8rem', fontWeight: '800', lineHeight: 1 }}>{value}</p>
    </div>
);

const chartContainerStyle = { 
    background: 'linear-gradient(135deg, #0f172a 0%, #1e293b 100%)', 
    padding: '35px 40px', 
    borderRadius: '24px', 
    boxShadow: '0 20px 25px -5px rgba(0, 0, 0, 0.1), 0 10px 10px -5px rgba(0, 0, 0, 0.04)', 
    display: 'flex', 
    alignItems: 'center', 
    justifyContent: 'flex-start', 
    flexDirection: 'column',
    border: '1px solid rgba(255,255,255,0.05)',
    position: 'relative'
};

const barStyle = (height, color) => ({
    width: '10%', 
    height: `${height}%`, 
    backgroundColor: color, 
    borderRadius: '8px 8px 0 0',
    opacity: 0.7,
    transition: 'all 0.3s cubic-bezier(0.4, 0, 0.2, 1)',
    cursor: 'pointer',
    position: 'relative'
});

export default AnalyticsDashboard;
